/* Chronicles of Power — client-only playable field edition. Historical content is kept separate from UI rendering. */
let {SOURCES,EVENTS,CAMPAIGN,NODES,INITIAL_STATE,OTHER_INFO}=window.COPContent;
const catalogIndex=window.CPCatalogIndex.build(EVENTS);
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
let game=null, selectedChoice=null, pendingNode=null, scale=1, toastTimer;
let worldMap=null, mapStarted=false, mapStyleReady=false, mapTileWarned=false, mapDidInitialFit=false, selectedMapEvent=null, geocodeTimer=null, resizeObserver=null;
const CATALOG_BATCH_SIZE=36,CATALOG_MAX_CARDS=108;
const catalogStates={library:{matches:[],start:0,end:0,observer:null},archive:{matches:[],start:0,end:0,observer:null}};
function esc(v){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function notify(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2400)}
function setView(view){$$('.view').forEach(x=>x.classList.remove('active-view'));const el=$(`#${view}-view`);if(el)el.classList.add('active-view');$$('.nav-link').forEach(b=>b.classList.toggle('active',b.dataset.view===view));if(view==='library'||view==='archive')renderCatalog(view);if(view==='map'&&worldMap)requestAnimationFrame(()=>{worldMap.resize();scheduleMapResize()});}
function playable(e){return e.imported===true||e.isPlayable===true||e.status==='playable'||e.simulationAvailable===true}
function renderEvents(filter='all',query=''){const list=$('#event-list');if(!list)return;const items=EVENTS.filter(e=>(filter==='all'||(filter==='playable'?playable(e):filter==='reference'?(e.imported===true||!playable(e)):!playable(e)))&&(`${e.title} ${e.place} ${e.category} ${e.period} ${e.year}`).toLowerCase().includes(query.toLowerCase())).slice(0,16);$('#catalog-count')&&($('#catalog-count').textContent=String(EVENTS.length).padStart(2,'0'));list.innerHTML=items.map(e=>`<article class="event-card" data-event="${e.id}" tabindex="0"><div class="event-thumb ${esc(e.art||'art-war')}"><span class="thumb-sigil">${esc(e.glyph||'✦')}</span></div><div class="event-info"><div class="event-meta">${esc(e.date||e.period||e.year)} · ${esc(e.category||'Historical event')}</div><div class="event-name">${esc(e.title)}</div><div class="event-place">${esc(e.place||'Location unavailable')}</div></div><span class="event-status ${playable(e)?'':'reference'}">${e.imported?'HYPOTHETICAL':playable(e)?(e.campaignType==='curated'?'CURATED':'SIMULATABLE'):'ARCHIVE'}</span></article>`).join('')||'<div class="empty-state">No events match this search.</div>';$$('.event-card',list).forEach(c=>{c.addEventListener('click',()=>openEvent(c.dataset.event));c.addEventListener('keydown',ev=>{if(ev.key==='Enter')openEvent(c.dataset.event)})})}
function catalogFilterId(prefix,name){const ids={search:'library-search',status:'status-filter',sort:'sort-filter',country:'country-filter',region:'region-filter',category:'category-filter',era:'era-filter',from:'date-from',to:'date-to'};return prefix==='library'?ids[name]:`${prefix}-${name}`}
function catalogFiltersMarkup(prefix){return `<input id="${catalogFilterId(prefix,'search')}" data-filter="search" placeholder="Search events, places, people, or sources…" aria-label="Search the complete historical catalogue"><select id="${catalogFilterId(prefix,'status')}" data-filter="status"><option value="all">All records</option><option value="curated">Curated campaigns</option><option value="simulation">Playable simulations</option><option value="archive">Read-only history records</option></select><select id="${catalogFilterId(prefix,'sort')}" data-filter="sort"><option value="oldest">Timeline · oldest first</option><option value="newest">Timeline · newest first</option><option value="relevance">Relevance</option></select><select id="${catalogFilterId(prefix,'country')}" data-filter="country"><option value="all">All countries / participants</option></select><select id="${catalogFilterId(prefix,'region')}" data-filter="region"><option value="all">All regions</option></select><select id="${catalogFilterId(prefix,'category')}" data-filter="category"><option value="all">All categories</option></select><select id="${catalogFilterId(prefix,'era')}" data-filter="era"><option value="all">All eras</option><option value="0">Before 500</option><option value="1">500–1499</option><option value="2">1500–1749</option><option value="3">1750–1899</option><option value="4">1900–present</option></select><label>FROM <input id="${catalogFilterId(prefix,'from')}" data-filter="from" type="number" min="1000" max="2026" value="1000"></label><label>TO <input id="${catalogFilterId(prefix,'to')}" data-filter="to" type="number" min="1000" max="2026" value="2026"></label>`}
function eventCardMarkup(e){return `<article class="campaign-card" data-event="${esc(e.id)}" tabindex="0"><div class="campaign-art ${esc(e.art||'art-war')}" aria-hidden="true"><span class="thumb-sigil">${esc(e.glyph||'✦')}</span></div><div class="campaign-card-body"><div class="event-meta">${esc(e.date||e.year)} · ${esc(e.category||'Historical event')}</div><h3>${esc(e.title)}</h3><p>${esc(e.summary||e.description||'No sourced description is available yet.')}</p><div class="card-cta"><span class="status-badge">${e.imported?'HYPOTHETICAL PLAYABLE':playable(e)?(e.campaignType==='curated'?'CURATED CAMPAIGN':'SCENARIO READY'):'HISTORY ARCHIVE'}</span><span>OPEN →</span></div></div></article>`}
function catalogMatches(view){const value=name=>{const control=$(`#${catalogFilterId(view,name)}`);return control?control.value:'all'};return catalogIndex.search({query:value('search'),status:value('status'),country:value('country'),region:value('region'),category:value('category'),era:value('era'),from:value('from'),to:value('to'),sort:value('sort')})}
function updateCatalogCount(view){const state=catalogStates[view],count=$(`#${view}-count`);count.textContent=state.matches.length?`Showing ${state.start+1}–${state.end} of ${state.matches.length.toLocaleString()} matching records · ${EVENTS.length.toLocaleString()} total`:`0 matching records · ${EVENTS.length.toLocaleString()} total`}
function cardBlockHeight(cards,grid){if(!cards.length)return 0;const first=cards[0].getBoundingClientRect(),last=cards.at(-1).getBoundingClientRect(),rows=new Set(cards.map(card=>Math.round(card.getBoundingClientRect().top))),gap=parseFloat(getComputedStyle(grid).rowGap)||0;return last.bottom-first.top+Math.max(0,rows.size-1)*gap}
function appendCatalogBatch(view){const state=catalogStates[view],grid=$(`#${view}-grid`);if(state.end>=state.matches.length)return;grid.querySelector('.catalog-sentinel')?.remove();const nextEnd=Math.min(state.end+CATALOG_BATCH_SIZE,state.matches.length);grid.insertAdjacentHTML('beforeend',state.matches.slice(state.end,nextEnd).map(eventCardMarkup).join(''));state.end=nextEnd;const cards=[...grid.querySelectorAll('.campaign-card')];if(cards.length>CATALOG_MAX_CARDS){const removed=cards.slice(0,CATALOG_BATCH_SIZE),height=cardBlockHeight(removed,grid);removed.forEach(card=>card.remove());state.start+=removed.length;grid.scrollTop=Math.max(0,grid.scrollTop-height)}if(state.end<state.matches.length)grid.insertAdjacentHTML('beforeend','<div class="catalog-sentinel" aria-hidden="true"></div>');updateCatalogCount(view);observeCatalogSentinel(view)}
function prependCatalogBatch(view){const state=catalogStates[view],grid=$(`#${view}-grid`);if(state.start<=0)return;const previousStart=Math.max(0,state.start-CATALOG_BATCH_SIZE),first=grid.querySelector('.campaign-card');first?.insertAdjacentHTML('beforebegin',state.matches.slice(previousStart,state.start).map(eventCardMarkup).join(''));state.start=previousStart;const cards=[...grid.querySelectorAll('.campaign-card')];if(cards.length>CATALOG_MAX_CARDS){cards.slice(-CATALOG_BATCH_SIZE).forEach(card=>card.remove());state.end-=CATALOG_BATCH_SIZE}updateCatalogCount(view);observeCatalogSentinel(view)}
function observeCatalogSentinel(view){const state=catalogStates[view],grid=$(`#${view}-grid`),sentinel=grid.querySelector('.catalog-sentinel');state.observer?.disconnect();if(!sentinel||!('IntersectionObserver'in window))return;state.observer=new IntersectionObserver(entries=>{if(entries.some(entry=>entry.isIntersecting))appendCatalogBatch(view)},{root:grid,rootMargin:'0px 0px 500px'});state.observer.observe(sentinel)}
function renderCatalog(view){const state=catalogStates[view],grid=$(`#${view}-grid`);state.observer?.disconnect();state.matches=catalogMatches(view);state.start=0;state.end=0;state.prependArmed=false;grid.scrollTop=0;grid.innerHTML=state.matches.length?'<div class="catalog-sentinel" aria-hidden="true"></div>':'<div class="empty-state">No historical records match these filters.</div>';if(state.matches.length)appendCatalogBatch(view);else updateCatalogCount(view)}
function renderSources(){$('#source-list').innerHTML=SOURCES.map((s,i)=>`<article class="source-item"><div class="source-num">0${i+1}</div><div><h3>${esc(s.title)}</h3><p>${esc(s.detail)}<br><span class="source-type">${esc(s.type)}</span></p></div><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">OPEN SOURCE ↗</a></article>`).join('')}
function setupSharedCatalogFilters(){for(const view of ['library','archive']){$(`[data-catalog-filters="${view}"]`).innerHTML=catalogFiltersMarkup(view);const countries=[...new Set(EVENTS.flatMap(e=>[...(e.countries||[]),e.country]).filter(value=>value&&value!=='Unspecified'))].sort(),regions=[...new Set(EVENTS.map(e=>e.region).filter(Boolean))].sort(),categories=[...new Set(EVENTS.map(e=>e.category).filter(Boolean))].sort();$(`#${catalogFilterId(view,'country')}`).insertAdjacentHTML('beforeend',countries.map(value=>`<option value="${esc(value)}">${esc(value)}</option>`).join(''));$(`#${catalogFilterId(view,'region')}`).insertAdjacentHTML('beforeend',regions.map(value=>`<option value="${esc(value)}">${esc(value)}</option>`).join(''));$(`#${catalogFilterId(view,'category')}`).insertAdjacentHTML('beforeend',categories.map(value=>`<option value="${esc(value)}">${esc(value)}</option>`).join(''));const filters=$(`[data-catalog-filters="${view}"]`);if(view==='archive'){filters.addEventListener('input',()=>renderCatalog(view));filters.addEventListener('change',()=>renderCatalog(view))}else{for(const type of ['country','region','category','era','from','to']){$(`#${catalogFilterId(view,type)}`).addEventListener('input',()=>renderCatalog(view));$(`#${catalogFilterId(view,type)}`).addEventListener('change',()=>renderCatalog(view))}}const grid=$(`#${view}-grid`);grid.addEventListener('click',event=>{const card=event.target.closest('.campaign-card');if(card)openEvent(card.dataset.event)});grid.addEventListener('keydown',event=>{const card=event.target.closest('.campaign-card');if(card&&(event.key==='Enter'||event.key===' ')){event.preventDefault();openEvent(card.dataset.event)}});grid.addEventListener('scroll',()=>{const state=catalogStates[view];if(grid.scrollTop>100)state.prependArmed=true;else if(grid.scrollTop<=50&&state.start>0&&state.prependArmed){state.prependArmed=false;prependCatalogBatch(view)}if(!('IntersectionObserver'in window)&&grid.scrollHeight-grid.scrollTop-grid.clientHeight<500)appendCatalogBatch(view)},{passive:true})}}
function renderLibrary(){renderCatalog('library')}
function openModal(html,gameModal=false){const b=$('#modal-backdrop'),m=$('#modal-content');m.className=`modal${gameModal?' game-modal':''}`;m.innerHTML=html;b.classList.remove('hidden');document.body.style.overflow='hidden';$('.hero-close',m)?.addEventListener('click',closeModal);b.onclick=e=>{if(e.target===b)closeModal()}}
function closeModal(){const b=$('#modal-backdrop');b.classList.add('hidden');document.body.style.overflow='';}
function openEvent(id){const e=EVENTS.find(x=>x.id===id);if(!e)return;window.COPAccount?.discoverEvent?.(e.id);if(e.imported&&!playable(e)){const sources=(e.sourceRefs||[]).map((url,i)=>`<a class="history-link" href="${esc(url)}" target="_blank" rel="noopener noreferrer">SOURCE ${i+1} ↗</a>`).join('');openModal(`<div class="campaign-hero ${esc(e.art||'art-war')}"><button class="hero-close">×</button><div><div class="hero-meta">${esc(e.date||e.year)} · ${esc(e.category||'Historical event')} · IMPORTED RECORD · UNREVIEWED</div><h1 class="hero-title">${esc(e.title)}</h1></div></div><div class="campaign-content"><div class="campaign-intro"><div><h3>Historical record</h3><p>${esc(e.summary||e.description||'No source description was available in the import.')}</p><p>${e.reviewStatus==="reviewed"?"This record has been human-reviewed but is not a playable scenario.":"This record has not been historically reviewed and is not a playable scenario."}</p></div><div class="campaign-facts"><div><small>COUNTRIES</small><strong>${esc((e.countries||[]).join(' · ')||'Not identified')}</strong></div><div><small>PEOPLE / PARTICIPANTS</small><strong>${esc((e.people||[]).join(' · ')||'Not identified')}</strong></div><div><small>SCENARIO STATUS</small><strong>${esc(e.scenarioStatus||'not-created')}</strong></div><div><small>ATTRIBUTION</small><strong>${esc(e.sourceAttribution||e.sourceName||'Wikimedia source')}</strong></div></div></div><div class="modal-actions">${sources}<button class="primary-button" id="archive-ok">CLOSE RECORD</button></div></div>`);$('#archive-ok').onclick=closeModal;return}if(e.campaignType!=='curated'&&id!=='emergency'){openModal(`<div class="campaign-hero ${e.art}"><button class="hero-close">×</button><div><div class="hero-meta">${esc(e.period)} · ${esc(e.category)} · HISTORICAL SIMULATION</div><h1 class="hero-title">${esc(e.title)}</h1></div></div><div class="campaign-content"><div class="campaign-intro"><div><h3>Historical record</h3><p>${esc(e.summary||e.description||'Limited historical information is available for this event.')} This scenario uses a deterministic model. Assumptions and outcomes are hypothetical, not historical claims.</p></div><div class="campaign-facts"><div><small>LOCATION</small><strong>${esc(e.place)}</strong></div><div><small>MODE</small><strong>Historical Simulation</strong></div><div><small>STARTING DATE</small><strong>${esc(e.date)}</strong></div></div></div><div class="modal-actions"><button class="history-link" id="event-sources">Browse archive</button><button class="primary-button" id="launch-simulation">PLAY SCENARIO →</button></div></div>`);$('#launch-simulation').onclick=()=>{closeModal();game=loadedSimulation(e.id)||newGenericGame(e);renderGenericGame()};$('#event-sources').onclick=()=>{closeModal();setView('archive')};return}
 if(e.status!=='playable'){openModal(`<div class="campaign-hero ${e.art}"><button class="hero-close">×</button><div><div class="hero-meta">${esc(e.period)} · ${esc(e.category)}</div><h1 class="hero-title">${esc(e.title)}</h1></div></div><div class="campaign-content"><div class="campaign-intro"><div><h3>Historical reference</h3><p>${esc(OTHER_INFO[id])}</p></div><div class="campaign-facts"><div><small>LOCATION</small><strong>${esc(e.place)}</strong></div><div><small>STATUS</small><strong>Archive entry · no playable scenario</strong></div><div><small>DATE</small><strong>${esc(e.date)}</strong></div></div></div><div class="modal-actions"><button class="history-link" id="open-archive-modal">Explore research sources</button><button class="primary-button" id="archive-ok">RETURN TO MAP</button></div></div>`);$('#archive-ok').onclick=closeModal;$('#open-archive-modal').onclick=()=>{closeModal();setView('archive')};return}
 const loaded=readSave();openModal(`<div class="campaign-hero"><button class="hero-close">×</button><div><div class="hero-meta">${CAMPAIGN.subtitle}</div><h1 class="hero-title">India’s <em>Emergency.</em></h1></div></div><div class="campaign-content"><div class="campaign-intro"><div><h3>A republic at the crossroads</h3><p>${CAMPAIGN.intro}</p></div><div class="campaign-facts">${CAMPAIGN.facts.map(f=>`<div><small>${f[0]}</small><strong>${f[1]}</strong></div>`).join('')}</div></div><div class="role-select"><label>ASSUME THE ROLE OF</label><div class="role-choice"><span class="role-portrait">IG</span><span><strong>Indira Gandhi</strong><small>Historical role · fictionalized gameplay dialogue</small></span></div></div><div class="modal-actions"><button class="history-link" id="campaign-sources">View sources & historical context</button><button class="primary-button" id="start-campaign">${loaded?'RESUME CAMPAIGN':'BEGIN CAMPAIGN'} →</button></div></div>`);$('#start-campaign').onclick=()=>{closeModal();if(loaded){game=loaded;notify('Campaign restored from local save.')}else game=newGame();renderGame();persist()};$('#campaign-sources').onclick=()=>{closeModal();setView('archive')}
}
function scenarioFor(event){const base=COPScenarios.build(event),authored=event.scenario;if(!authored)return base;return{...base,...authored,id:authored.id||base.id,roles:authored.roles?.length?authored.roles:base.roles,sourceRefs:authored.sourceRefs||base.sourceRefs,startingState:authored.startingState||base.startingState,objectives:authored.objectives||base.objectives,supportedActions:authored.supportedActions||base.supportedActions,assumptions:authored.assumptions||base.assumptions,maxTurns:authored.maxTurns||base.maxTurns,tier:'authored',hypothetical:false}}
function newGenericGame(event){const scenario=scenarioFor(event);return {...COPScenarios.initialize(event,scenario.roles[0],scenario),campaignId:event.id,scenarioId:scenario.id}}
function loadedSimulation(id){try{const value=JSON.parse(localStorage.getItem(`cop-sim-${id}`));return value?.eventId===id&&COPSimulation.validateSave(value,Math.max(0,value.node||0))?value:null}catch{return null}}
function saveGeneric(){localStorage.setItem(`cop-sim-${game.eventId}`,JSON.stringify(game));window.COPAccount?.gameChanged?.(game)}
function renderGenericGame(message=''){const event=EVENTS.find(x=>x.id===game.eventId);if(!event)return;const scenario=scenarioFor(event),items=EVENTS.filter(x=>x.id!==event.id&&x.category===event.category).slice(0,3),roles=scenario.roles,refs=scenario.sourceRefs.map((url,i)=>`<a class="history-link" href="${esc(url)}" target="_blank" rel="noopener noreferrer">SOURCE ${i+1} --</a>`).join(''),actions=scenario.supportedActions;openModal(`<div class="game-top"><div class="game-top-title">CHRONICLES / ${esc(event.title.toUpperCase())} | ${event.imported?'HYPOTHETICAL SCENARIO':'HISTORICAL SIMULATION'}</div><div class="game-top-right"><span>TURN ${game.turn||0} / ${scenario.maxTurns||6}</span><button id="game-close">EXIT SIMULATION [X]</button></div></div><div class="game-body"><section class="game-main"><div class="game-kicker">${event.imported?'HYPOTHETICAL SCENARIO | ':'SCENARIO BRIEFING | '}${esc(scenario.date)}</div><h2>${esc(event.title)}</h2><p class="game-brief">${esc(scenario.context)} ${esc(OTHER_INFO[event.id]||'')}</p><div class="simulation-assumptions"><b>HISTORICAL RECORD</b><span>${esc(event.summary||event.description||'Limited historical information is available for this imported record.')} | ${esc(event.place||event.region||'Geography unspecified')} | Tier ${scenario.tier||'authored'}</span></div><div class="simulation-assumptions"><b>PRIMARY OBJECTIVE</b><span>${scenario.objectives.map(esc).join(' | ')}</span></div><div class="simulation-role"><label for="simulation-role">PLAYABLE PARTICIPANT / ROLE</label><select id="simulation-role">${roles.map(role=>`<option ${game.role===role?'selected':''}>${esc(role)}</option>`).join('')}</select></div><div class="simulation-assumptions"><b>STARTING CONDITIONS | HYPOTHETICAL GAME SCALES</b><span>Stability, trust, liberties, and legitimacy begin at 50/100. These are game values, not historical measurements.</span></div><div class="simulation-assumptions"><b>ASSUMPTIONS & CONSTRAINTS</b><span>${[...scenario.assumptions,...(scenario.constraints||[])].map(esc).join(' | ')}</span></div><div class="game-kicker">AVAILABLE DECISIONS | CONSEQUENCES ARE HYPOTHETICAL</div><div class="scenario-actions">${actions.map(action=>`<button class="scenario-action" data-scenario-action="${esc(action)}" ${game.ended?'disabled':''}>${esc(action)} / APPLY</button>`).join('')}</div><div class="freeform-wrap"><label for="freeform-action">OR WRITE YOUR OWN DECISION</label><textarea id="freeform-action" rows="2" placeholder="Describe a diplomatic, civic, economic, or political action..." ${game.ended?'disabled':''}></textarea><button class="primary-button" id="submit-action" ${game.ended?'disabled':''}>VALIDATE & APPLY</button><button class="primary-button" id="ai-preview-decision" type="button" ${game.ended?'disabled':''}>ASK LOCAL AI FOR A PROPOSAL</button></div><div class="ai-preview" id="ai-decision-preview" aria-live="polite"></div><div class="ai-feature-grid"><section class="ai-feature"><div class="game-kicker">FICTIONAL DIPLOMATIC CHANNEL</div><p class="ai-feature-caption">Dialogue with <strong data-ai-counterpart></strong>. No treaty is made automatically.</p><textarea id="ai-diplomacy-input" rows="2" maxlength="700" placeholder="Write a diplomatic message..."></textarea><button class="history-link" id="ai-diplomacy-send" type="button">SEND MESSAGE</button><div class="ai-diplomacy-log" id="ai-diplomacy-log" aria-live="polite"></div></section><section class="ai-feature"><div class="game-kicker">ALTERNATE EVENT GENERATOR</div><p class="ai-feature-caption">Request one pending fictional event. Accepting it still requires a valid engine action.</p><button class="history-link" id="ai-event-request" type="button" ${game.ended?'disabled':''}>PROPOSE AN EVENT</button><div class="ai-preview" id="ai-event-preview" aria-live="polite"></div></section></div><div class="simulation-message" id="simulation-message">${message}${game.ended?`<br><strong>SCENARIO COMPLETE | ${esc(game.outcome)}</strong>`:''}</div><div class="game-kicker">ALTERNATE TIMELINE | ${esc(game.date)}</div><div class="timeline-list" id="generic-timeline">${timelineHtml()}</div><div class="modal-actions">${refs}<button class="history-link" id="restart-scenario">RESTART SCENARIO [R]</button></div>${items.length?`<div class="game-kicker">RELATED CATALOG ENTRIES</div><div class="related-events">${items.map(x=>`<button data-related="${x.id}">${esc(x.title)} ?</button>`).join('')}</div>`:''}</section><aside class="game-side"><div class="side-label">MODELED INDICATORS <span title="Invented gameplay scales">i</span></div><div class="state-list">${stateBars()}</div><div class="timeline-mini"><div class="side-label">SCENARIO FRAME</div><p>${esc(scenario.theme||event.category||'Historical theme')}. No map or territorial changes are implied by these abstract indicators.</p></div><div class="game-side-bottom"><button id="game-save">SAVE SIMULATION</button><button id="simulation-exit">RETURN TO MAP</button></div></aside></div><div class="game-footer"><span>${event.imported?'HYPOTHETICAL FALLBACK':'SIMULATION'} | NOT A HISTORICAL FORECAST</span><span>LOCAL SINGLE-PLAYER | ${game.choices.length} DECISIONS</span></div>`,true);$('#game-close').onclick=closeModal;$('#simulation-exit').onclick=closeModal;$('#game-save').onclick=()=>{saveGeneric();notify('Simulation saved on this device.')};$('#submit-action').onclick=()=>submitGenericAction();$('#simulation-role').onchange=e=>{game.role=e.target.value;saveGeneric()};$('#freeform-action').onkeydown=e=>{if((e.ctrlKey||e.metaKey)&&e.key==='Enter')submitGenericAction()};$$('[data-scenario-action]').forEach(b=>b.onclick=()=>submitGenericAction(b.dataset.scenarioAction));$('#restart-scenario').onclick=()=>{game=newGenericGame(event);saveGeneric();renderGenericGame('Scenario restarted from its alternate-history starting point.')};$$('[data-related]').forEach(b=>b.onclick=()=>openEvent(b.dataset.related))}
function submitGenericAction(actionOverride,generatedEvent=null){
  if(!game||game.mode!=='historical-simulation'||game.ended)return;
  const input=$('#freeform-action'),action=(actionOverride||input?.value||'').trim(),event=EVENTS.find(x=>x.id===game.eventId),scenario=scenarioFor(event),message=$('#simulation-message');
  const result=COPSimulation.interpretAction(action,{scenarioId:event.id,date:scenario.date,role:game.role,allowedRoles:scenario.roles});
  if(result.clarification){message.textContent=result.clarification;message.className='simulation-message clarification';return;}
  if(!scenario.supportedActions.includes(result.label)){message.textContent='That action is not supported by this scenario. Choose a listed action or rephrase your order.';message.className='simulation-message clarification';return;}
  game.state=COPSimulation.applyEffects(game.state,result.effects);game.choices.push({node:game.node++,title:result.label,action,effects:result.effects});game.entries.push({date:game.date,text:'HYPOTHETICAL | '+result.label+': "'+action+'"',kind:'hypothetical'});
  if(generatedEvent){const accepted={id:generatedEvent.id,title:generatedEvent.title,narrative:generatedEvent.narrative,date:game.date,actionText:result.label,kind:'alternate-history',status:'accepted',historical:false,acceptedAt:new Date().toISOString()};game.generatedEvents=[...(game.generatedEvents||[]),accepted];game.entries.push({date:game.date,text:'ALTERNATE EVENT | '+accepted.title+': '+accepted.narrative,kind:'generated'});try{const key='cop-alt-events-'+game.eventId,stored=JSON.parse(localStorage.getItem(key)||'[]');stored.push(accepted);localStorage.setItem(key,JSON.stringify(stored));}catch(error){console.warn('[Chronicles alternate events] Local storage unavailable.',error);}}
  if(worldMap&&event.coordinates){worldMap.flyTo({center:event.coordinates,zoom:Math.max(worldMap.getZoom(),4.7),duration:1000,essential:true});setSelectedPoint(...event.coordinates);}
  COPScenarios.nextTurn(game,Number(event.year));const ending=COPScenarios.evaluateOutcome(game),outcome='HYPOTHETICAL | '+result.label+' applied. Modeled indicators changed: '+effectText(result.effects)+'. '+(ending==='in-progress'?'The next modeled turn begins.':'Outcome: '+ending+'.');saveGeneric();renderGenericGame(outcome);
}
function newGame(){return {campaignId:'emergency',scenarioId:'emergency',node:0,turn:0,date:NODES[0]?.date||'25 JUN 1975',state:{...INITIAL_STATE},choices:[],entries:[{date:'25 JUN 1975',text:'Emergency proclaimed',kind:'historical'}],ended:false,created:Date.now()}}
function readSave(){try{const v=JSON.parse(localStorage.getItem('cop-save'));return validGame(v)?v:null}catch{return null}}
function validGame(v){return COPSimulation.validateSave(v,NODES.length)}
function persist(){if(game){if(game.mode==='historical-simulation'){saveGeneric();$('#save-button').title='Simulation saved on this device';window.COPAccount?.gameChanged?.(game);return}localStorage.setItem('cop-save',JSON.stringify(game));$('#save-button').title='Saved on this device';window.COPAccount?.gameChanged?.(game)}}
function stateBars(){const labels={stability:'Government stability',trust:'Public trust',liberties:'Civil liberties',legitimacy:'Political legitimacy'};return Object.entries(labels).map(([k,l])=>`<div class="state-row"><label>${l}</label><b>${game.state[k]}</b><div class="state-track"><i style="width:${game.state[k]}%"></i></div></div>`).join('')}
function timelineHtml(){return game.entries.slice(-4).reverse().map(e=>`<div class="timeline-entry"><small>${esc(e.date)} ${e.kind==='hypothetical'?'· SIMULATED':'· HISTORICAL'}</small>${esc(e.text)}</div>`).join('')}
function renderGame(){const ended=game.ended||game.node>=NODES.length;const ending=ended?getEnding():null;const node=NODES[Math.min(game.node,NODES.length-1)];const opts=ended?[]:node.options;openModal(`<div class="game-top"><div class="game-top-title">CHRONICLES <span style="color:#8b815f">/</span> INDIA · THE EMERGENCY</div><div class="game-top-right"><span>✳ &nbsp;${game.choices.length}/3 DECISIONS</span><button id="game-close">EXIT CAMPAIGN ×</button></div></div><div class="game-body"><section class="game-main"><div class="game-kicker">${ended?'CAMPAIGN CONCLUSION':'DECISION '+(game.node+1)+' · '+node.date}</div>${ended?`<div class="ending-banner"><small>${ending.label}</small><h2>${ending.title}</h2><p>${ending.text}</p></div><div class="game-kicker">YOUR ALTERNATE TIMELINE</div><div class="timeline-list">${timelineHtml()}</div>`:`<h2>${node.title}</h2><p class="game-brief">${node.brief}</p><div class="decision-options">${opts.map(o=>`<button class="decision-option" data-choice="${o.id}"><strong>${o.title}</strong><span>${o.desc}</span></button>`).join('')}</div><div class="decision-actions"><button class="primary-button" id="confirm-choice" disabled>CONFIRM DECISION →</button><button class="briefing-toggle" id="briefing-toggle">Historical briefing +</button></div><div class="historical-note hidden" id="historical-note">${node.historic}</div>`}<button class="game-assistant" id="game-archivist">✳ &nbsp; ASK THE ARCHIVIST</button></section><aside class="game-side"><div class="side-label">SIMULATION INDICATORS <span title="Invented gameplay scales">ⓘ</span></div><div class="state-list">${stateBars()}</div><div class="timeline-mini"><div class="side-label">ALTERNATE TIMELINE</div><div class="mini-track"></div><div class="mini-dates"><span>1975</span><span>YOUR PRESENT</span><span>1977</span></div><div class="timeline-list">${timelineHtml()}</div></div><div class="game-side-bottom"><button id="replay-campaign">↻ RESTART</button><button id="game-save">◈ SAVE LOCALLY</button><button id="compare-history">HISTORY ↗</button></div></aside></div><div class="game-footer"><span>SIMULATED OUTCOMES ARE SPECULATIVE · HISTORY IS SHOWN AS DOCUMENTED</span><span>LOCAL SINGLE-PLAYER</span></div>`,true);
 $('#game-close').onclick=closeModal;$('#game-save').onclick=()=>{persist();notify('Campaign saved on this device.')};$('#replay-campaign').onclick=()=>{game=newGame();renderGame();notify('A new playthrough has begun.')};$('#compare-history').onclick=()=>showComparison();$('#game-archivist').onclick=()=>{closeModal();openArchivist(true)};
 $$('.decision-option').forEach(b=>{const option=NODES[game.node]?.options.find(x=>x.id===b.dataset.choice);if(option&&!COPSimulation.isAvailable(option,game.state,game.choices)){b.classList.add('locked');b.disabled=true;b.querySelector('span').textContent='LOCKED · '+COPSimulation.lockReason(option,game.state,game.choices)}});$$('.decision-option').forEach(b=>b.onclick=()=>{$$('.decision-option').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');selectedChoice=b.dataset.choice;$('#confirm-choice').disabled=false});$('#confirm-choice')?.addEventListener('click',confirmDecision);$('#briefing-toggle')?.addEventListener('click',()=>{const n=$('#historical-note');n.classList.toggle('hidden');$('#briefing-toggle').textContent=n.classList.contains('hidden')?'Historical briefing +':'Historical briefing −'});
}
function confirmDecision(){if(!game||selectedChoice===null)return;const node=NODES[game.node],choice=node.options.find(o=>o.id===selectedChoice);if(!choice||!COPSimulation.isAvailable(choice,game.state,game.choices))return;game.state=COPSimulation.applyEffects(game.state,choice.effects);game.choices.push({node:node.id,choice:choice.id,title:choice.title});game.entries.push({date:node.date,text:choice.title,kind:'hypothetical'});if(game.node===0)game.entries.push({date:'JUL 1975',text:'Information policy becomes a central test',kind:'historical'});game.node++;pendingNode={choice,node};selectedChoice=null;persist();selectMarker('emergency');renderGame();showConsequence(choice,node);}
function showConsequence(choice,node){const main=$('.game-main');if(!main)return;const data=`<div class="consequence-backdrop"><div class="consequence-head"><small>DECISION CONFIRMED · SIMULATED OUTCOME</small><button id="continue-consequence">CONTINUE →</button></div><h3>${esc(choice.outcome.split('.')[0])}.</h3><p>${esc(choice.outcome)} These are modelled possibilities, not verified historical events.</p><div class="cause-map"><div class="cause-node"><i>◉</i><span>EXECUTIVE</span><small>IMMEDIATE EFFECT</small></div><div class="cause-link"></div><div class="cause-node"><i>⌁</i><span>PUBLIC SPHERE</span><small>SECONDARY EFFECT</small></div><div class="cause-link second"></div><div class="cause-node"><i>✳</i><span>YOUR NEXT CHOICE</span><small>BRANCH UNLOCKED</small></div></div><div class="effect-cards"><article class="effect-card"><small>IMMEDIATE · MODELLED</small><strong>${effectText(choice.effects)}</strong><p>${esc(choice.outcome)}</p></article><article class="effect-card hypothetical"><small>DELAYED · UNCERTAIN</small><strong>Possible ripple effect</strong><p>${esc(choice.delay)}</p></article><article class="effect-card"><small>HISTORICAL RECORD</small><strong>Separate fact from fiction</strong><p>This branch is simulated. See the History Archive for sourced context on the real period.</p></article></div></div>`;main.insertAdjacentHTML('beforeend',data);$('#continue-consequence').onclick=()=>{game.ended=game.node>=NODES.length;persist();renderGame()}}
function effectText(e){return Object.entries(e).map(([k,v])=>`${k} ${v>0?'+':''}${v}`).join(' · ')}
function getEnding(){const type=COPSimulation.endingFor(game.state);return ({'open-mandate':{label:'ENDING · OPENING TO THE ELECTORATE',title:'A return to public mandate',text:'Your simulated choices preserve space for scrutiny and lead toward renewed electoral competition. The actual 1977 result remains distinct from this counterfactual path.'},'legitimacy-strain':{label:'ENDING · LEGITIMACY UNDER STRAIN',title:'Control without confidence',text:'Restrictions and low public trust leave institutions brittle. This speculative ending is a model outcome, not a claim about what would certainly have happened.'},'uneasy-calm':{label:'ENDING · AN UNEASY CALM',title:'Order, with questions unanswered',text:'The government retains short-term stability, while political legitimacy and civil liberties remain contested in this simulated outcome.'},'negotiated-transition':{label:'ENDING · NEGOTIATED TRANSITION',title:'A narrow path forward',text:'Your choices leave a mixed legacy: pressure persists, but there is room for a political transition. This is one speculative model among many.'}})[type]}
function showComparison(){const hist=`<div class="consequence-backdrop"><div class="consequence-head"><small>HISTORY COMPARISON · DOCUMENTED RECORD</small><button id="continue-consequence">RETURN TO CAMPAIGN →</button></div><h3>What happened in recorded history</h3><p>In January 1977, Indira Gandhi announced elections. Voting took place in March; the opposition Janata alliance won, and the Emergency was revoked on 21 March 1977. These are documented historical milestones. Your decisions and ending are alternate-history simulation.</p><div class="cause-map"><div class="cause-node"><i>§</i><span>25 JUN 1975</span><small>PROCLAMATION</small></div><div class="cause-link"></div><div class="cause-node"><i>▤</i><span>JAN 1977</span><small>ELECTION ANNOUNCED</small></div><div class="cause-link second"></div><div class="cause-node"><i>✓</i><span>MAR 1977</span><small>EMERGENCY REVOKED</small></div></div><div class="effect-cards"><article class="effect-card"><small>HISTORICAL SOURCE</small><strong>Government of India</strong><p>PIB Archives factsheet documents the period as 25 June 1975–21 March 1977.</p></article><article class="effect-card"><small>HISTORICAL SOURCE</small><strong>Election Commission of India</strong><p>Official statistical reports include the 1977 general election.</p></article><article class="effect-card hypothetical"><small>YOUR PLAYTHROUGH</small><strong>${getEnding().title}</strong><p>Your choices are simulated and do not alter the historical record.</p></article></div></div>`;$('.game-main').insertAdjacentHTML('beforeend',hist);$('#continue-consequence').onclick=()=>renderGame()}

function openArchivist(inGame=false){$('#archivist-panel').classList.add('open');const ctx=window.COPRuntime?.context?.();$('#archivist-context').textContent=game&&inGame&&ctx?'Scenario: '+ctx.eventTitle+' | '+ctx.date+' | '+game.choices.length+' simulated decisions':'Context: '+(ctx?.eventTitle||'Historical event discovery')+' | local AI is optional';$('#chat-input').focus();}
function answerArchivist(q){const low=q.toLowerCase(),active=EVENTS.find(x=>x.id===(game?.eventId||selectedMapEvent));if(active&&active.id!=='emergency'){const refs=(active.sourceRefs||[]).filter(url=>/^https:\/\//.test(url)).slice(0,5).map((url,i)=>'<a class="chat-citation" href="'+esc(url)+'" target="_blank" rel="noopener noreferrer">SOURCE '+(i+1)+' ?</a>').join('');addChat('assistant','The local model is unavailable. The imported record says: '+(active.summary||active.description||'No description was included.')+' This record is still marked unverified; I cannot add historical details beyond its supplied text.',refs);return;}let answer,cite;if(/source|citation|evidence|where/.test(low)){answer='For this scenario, the campaign records cite the Government of India PIB Archives factsheet for the Emergency dates and Shah Commission remit, the Shah Commission archival collection at Ashoka University, parliamentary records, the Ministry of Home Affairs Gazette, and Election Commission of India election publications. These are source leads, not a substitute for checking each claim against the underlying documents.';cite=[0,1,2,3,4]}else if(/histor|real|document|actual|fact/.test(low)){answer='The recorded period ran from 25 June 1975 to 21 March 1977. The proclamation was issued under Article 352. Press censorship, preventive detention, and questions about state power were examined by the Shah Commission. The game’s choice dialogue, indicator scores, causal links, and alternate endings are fictional simulation elements.';cite=[0,1,4]}else if(/what was|emergency|why/.test(low)){answer='India’s Emergency was a 21-month period beginning 25 June 1975, when a national Emergency was proclaimed under Article 352. The official PIB Archives summary notes the Shah Commission later examined abuses including preventive detention and press censorship. Causes and interpretations are contested; consult the archival report and parliamentary records for detail.';cite=[0,1,2]}else if(/branch|unlock|choice|decision|my timeline|outcome|happen/.test(low)&&game){answer=`Your current branch reflects the choices you selected and the simulation indicators shown in the campaign. The engine applies deterministic score changes from the scenario data; later decisions can respond to those scores in the ending summary. Any predicted ripple effect is a hypothetical game model, not a certain forecast or historical fact. Current indicators: stability ${game.state.stability}, public trust ${game.state.trust}, civil liberties ${game.state.liberties}, legitimacy ${game.state.legitimacy}.`;cite=[0,1]}else if(/leader|indira|gandhi|quotation|quote/.test(low)){answer='This prototype treats Indira Gandhi as the historical role selected for play, but it does not generate or attribute dialogue to her. All in-game speeches and decision framing are fictionalized. For documented actions, consult parliamentary and archival records; no quotation is presented here.';cite=[1,2,4]}else{answer='I can answer from the campaign’s compact source-backed record: dates, the constitutional proclamation, the Shah Commission, the 1977 election, and the distinction between historical record and simulated choices. I do not have live retrieval or a connected language model in this prototype, so I will not guess beyond those records.';cite=[0,1,3]}
const citations=cite.map(i=>`<a class="chat-citation" href="${esc(SOURCES[i].url)}" target="_blank" rel="noopener noreferrer">${esc(SOURCES[i].title)} ↗</a>`).join('');addChat('assistant',answer,citations)}
function addChat(who,text,citations=''){const log=$('#chat-log');const div=document.createElement('div');div.className=`chat-message ${who}`;div.innerHTML=who==='assistant'?`<span class="chat-icon">✳</span><p>${esc(text)}${citations}</p>`:`<p>${esc(text)}</p>`;log.append(div);log.scrollTop=log.scrollHeight}

function selectMarker(id){const event=EVENTS.find(item=>item.id===id);if(!event)return;if(!Array.isArray(event.coordinates)){openEvent(id);return}const previous=selectedMapEvent;selectedMapEvent=id;if(worldMap?.getSource('campaign-events')){if(previous)worldMap.setFeatureState({source:'campaign-events',id:previous},{selected:false});worldMap.setFeatureState({source:'campaign-events',id},{selected:true});worldMap.flyTo({center:event.coordinates||[0,20],zoom:Math.max(worldMap.getZoom(),4.8),duration:1500,essential:true,curve:1.35});pulseEventMarker()}renderEvents('all',event.title);$('#world-era').textContent=event.period.toUpperCase();$('#map-tooltip').textContent=`${event.title} · ${event.period}`;$('#map-tooltip').classList.remove('hidden');setTimeout(()=>$('#map-tooltip').classList.add('hidden'),2100);if(window.innerWidth<780)$('#event-list').scrollIntoView({behavior:'smooth',block:'nearest'})}
