function scheduleMapResize(){if(!worldMap)return;requestAnimationFrame(()=>{if(!worldMap)return;worldMap.resize();if(!mapDidInitialFit&&mapStyleReady)fitWholeWorld(0)})}
function fitWholeWorld(duration=1100){if(!worldMap)return;const height=worldMap.getContainer().clientHeight,worldZoom=Math.min(.55,Math.log2(Math.max(350,height-48)/512)),camera={center:[0,0],zoom:worldZoom,pitch:0,bearing:0};if(duration)worldMap.flyTo({...camera,duration,essential:true});else worldMap.jumpTo(camera);mapDidInitialFit=true}
function initializeMap(){if(mapStarted)return;mapStarted=true;mapStyleReady=false;mapTileWarned=false;if(!window.maplibregl){showMapFallback('MapLibre could not load. Check your connection, then try again.');return}try{const host=$('#world-map');worldMap=new window.maplibregl.Map({container:host,style:'https://demotiles.maplibre.org/style.json',center:[0,18],zoom:0.8,minZoom:0.4,maxZoom:13,attributionControl:true,fadeDuration:300,renderWorldCopies:false,projection:'mercator',pitch:0,maxPitch:50,dragRotate:true,cooperativeGestures:false,scrollZoom:{around:'center'}});window.worldMap=worldMap;worldMap.addControl(new window.maplibregl.NavigationControl({showCompass:true,showZoom:false,visualizePitch:true}),'bottom-right');resizeObserver=new ResizeObserver(scheduleMapResize);resizeObserver.observe($('.map-stage'));resizeObserver.observe($('#side-panel'));worldMap.once('style.load',()=>{mapStyleReady=true;worldMap.resize();fitWholeWorld(0);applyAtlasPalette();buildMarkers();$('#map-fallback')?.classList.add('hidden');const range=$('#period-range');if(range)applyPeriodFilter();updateMapCoordinates()});worldMap.once('load',()=>{requestAnimationFrame(()=>{if(worldMap&&mapStyleReady){worldMap.resize();fitWholeWorld(0)}})});setTimeout(()=>{if(worldMap&&mapStyleReady&&!selectedMapEvent)fitWholeWorld(0)},1200);worldMap.on('moveend',updateMapCoordinates);worldMap.on('click',event=>{const layers=['event-dots','event-labels'].filter(id=>worldMap.getLayer(id));const features=layers.length?worldMap.queryRenderedFeatures(event.point,{layers}):[];if(features.length)return;handleMapLocation(event.lngLat.lng,event.lngLat.lat)});worldMap.on('error',event=>{console.error('[Chronicles map]',event.error||event);if(!mapStyleReady)showMapFallback('Map style failed to load. Check your connection, then retry.');else if(event.sourceId&&!mapTileWarned){mapTileWarned=true;notify('Some geographic tiles could not load; see the browser console for details.')}});setTimeout(()=>{if(worldMap&&!mapStyleReady)showMapFallback('Map style is taking too long to load. Check your connection and retry.')},12000)}catch(error){console.error('[Chronicles map initialization]',error);showMapFallback('This browser could not start WebGL map rendering. Use a current browser with hardware acceleration enabled.')}}
function updateMapCoordinates(){if(!worldMap)return;const center=worldMap.getCenter();const format=value=>`${Math.abs(value).toFixed(2)}° ${value>=0?'N':'S'}`;const formatLng=value=>`${Math.abs(value).toFixed(2)}° ${value>=0?'E':'W'}`;$('#map-coordinates').textContent=`WORLD VIEW · ${format(center.lat)} / ${formatLng(center.lng)} · WGS84`}
function showMapFallback(message){const fallback=$('#map-fallback');if(!fallback)return;fallback.classList.remove('hidden');fallback.innerHTML=`<span class="fallback-kicker">WORLD ATLAS · OFFLINE</span><strong>${esc(message)}</strong><button id="retry-map" class="map-retry">RETRY CONNECTION ↗</button>`;$('#retry-map').onclick=async()=>{resizeObserver?.disconnect();resizeObserver=null;worldMap?.remove();worldMap=null;mapStarted=false;mapDidInitialFit=false;fallback.innerHTML='<span class="fallback-kicker">WORLD ATLAS · CONNECTING</span><strong>Loading geographic layers</strong><p>Connecting to public MapLibre terrain tiles.</p>';if(!window.maplibregl){try{window.maplibregl=await import('https://unpkg.com/maplibre-gl@6.14.0/dist/maplibre-gl.mjs')}catch{mapStarted=true;return showMapFallback('Map library is still unavailable. Check your connection and retry.')}}initializeMap()}}
async function handleMapLocation(lng,lat){setSelectedPoint(lng,lat);$('#map-tooltip').textContent=`${lat.toFixed(2)}°, ${lng.toFixed(2)}° · resolving place…`;$('#map-tooltip').classList.remove('hidden');try{const response=await fetch(`https://photon.komoot.io/reverse?lon=${encodeURIComponent(lng)}&lat=${encodeURIComponent(lat)}`);if(!response.ok)throw new Error('Place lookup unavailable');const data=await response.json(),place=data.features?.[0]?.properties||{};const name=place.name||place.city||place.county||`${lat.toFixed(2)}°, ${lng.toFixed(2)}°`;const country=place.country||'';const related=EVENTS.filter(event=>`${event.place} ${event.title}`.toLowerCase().includes((country||name).toLowerCase()));$('#map-tooltip').textContent=[name,country].filter(Boolean).join(', ');showLocationBriefing(name,country,related,lng,lat)}catch{const name=`${lat.toFixed(2)}° N, ${lng.toFixed(2)}° E`;$('#map-tooltip').textContent=`Selected location · ${name}`;showLocationBriefing(name,'',[],lng,lat)}}
function setSelectedPoint(lng,lat){if(!worldMap)return;const feature={type:'Feature',geometry:{type:'Point',coordinates:[lng,lat]},properties:{}};if(worldMap.getSource('selected-place'))worldMap.getSource('selected-place').setData(feature);else{worldMap.addSource('selected-place',{type:'geojson',data:feature});worldMap.addLayer({id:'selected-place-glow',type:'circle',source:'selected-place',paint:{'circle-radius':18,'circle-color':'#e8cb82','circle-opacity':0.22,'circle-blur':0.7}});worldMap.addLayer({id:'selected-place-point',type:'circle',source:'selected-place',paint:{'circle-radius':5,'circle-color':'#f2dfa9','circle-stroke-color':'#151a20','circle-stroke-width':2}})}}
function showLocationBriefing(name,country,related,lng,lat){const eventRows=related.length?related.map(event=>`<button class="location-event" data-location-event="${event.id}"><span class="location-event-date">${esc(event.period)}</span><strong>${esc(event.title)}</strong><small>${playable(event)?'SIMULATABLE':'HISTORY ARCHIVE'}</small></button>`).join(''):'<p class="location-empty">No catalog record in this location yet. You can still explore the selected coordinates.</p>';openModal(`<div class="location-hero"><button class="hero-close">×</button><span class="hero-meta">WORLD ATLAS · SELECTED LOCATION</span><h2>${esc(name)}</h2><p>${esc(country||`${lat.toFixed(3)}, ${lng.toFixed(3)}`)}</p></div><div class="campaign-content location-content"><div class="location-event-list">${eventRows}</div><div class="modal-actions"><button class="history-link" id="location-archive">Browse the history archive</button><button class="primary-button" id="location-dismiss">RETURN TO MAP</button></div></div>`);$('#location-dismiss').onclick=closeModal;$('#location-archive').onclick=()=>{closeModal();setView('archive')};$$('[data-location-event]').forEach(button=>button.onclick=()=>{const id=button.dataset.locationEvent;closeModal();openEvent(id)})}
function wire(){ $$('.nav-link').forEach(b=>b.onclick=()=>setView(b.dataset.view));$$('[data-view="map"]').forEach(b=>b.onclick=()=>setView('map'));$('#show-library').onclick=()=>setView('library');$('#all-events').onclick=()=>setView('library');$$('.filter-pill').forEach(b=>b.onclick=()=>{$$('.filter-pill').forEach(x=>x.classList.remove('active'));b.classList.add('active');renderEvents(b.dataset.filter)});$('#library-search').oninput=renderLibrary;$('#status-filter').onchange=renderLibrary;$('#sort-filter').onchange=renderLibrary;$('#save-button').onclick=()=>{if(game){persist();notify('Campaign saved on this device.')}else{const s=readSave();notify(s?'Saved campaign is ready to resume.':'Start a campaign to create a local save.')}};$('#archivist-open').onclick=()=>openArchivist(false);$('#archivist-close').onclick=()=>$('#archivist-panel').classList.remove('open');$('#chat-form').onsubmit=e=>{e.preventDefault();const inp=$('#chat-input'),q=inp.value.trim();if(!q)return;addChat('user',q);inp.value='';setTimeout(()=>answerArchivist(q),180)};$$('.suggested-questions button').forEach(b=>b.onclick=()=>{const q=b.textContent;addChat('user',q);answerArchivist(q)});$('#zoom-in').onclick=()=>zoom(.12);$('#zoom-out').onclick=()=>zoom(-.12);$('#reset-map').onclick=()=>{scale=1;updateZoom()};$('#map-search').oninput=searchMap;$('#period-range').oninput=e=>{$('#world-era').textContent=['ANCIENT','MEDIEVAL','EARLY MODERN','INDUSTRIAL','20TH CENTURY','ALL ERAS'][e.target.value];const yr=+e.target.value;const range=yr===5?EVENTS:EVENTS.filter(x=>yr===4?x.year>=1900:yr===3?x.year>=1750&&x.year<1900:yr===2?x.year>=1500&&x.year<1750:yr===1?x.year>=500&&x.year<1500:x.year<500);renderEvents('all');$$('.event-card').forEach(c=>{const ev=EVENTS.find(x=>x.id===c.dataset.event);c.style.opacity=range.includes(ev)?'1':'.28'});$$('.marker').forEach(m=>{const ev=EVENTS.find(x=>x.id===m.dataset.event);m.style.opacity=range.includes(ev)?'1':'.18'})};$('#period-select').onclick=()=>{$('#period-range').focus();notify('Use the historical lens slider to filter the map.')};$$('.layer-chip').forEach(b=>b.onclick=()=>{b.classList.toggle('selected');if(b.dataset.layer==='routes')$('.route-lines').style.opacity=b.classList.contains('selected')?'.48':'0';if(b.dataset.layer==='campaigns')$$('.marker').forEach(m=>{const e=EVENTS.find(x=>x.id===m.dataset.event);m.style.display=b.classList.contains('selected')||e.status==='reference'?'':'none'});if(b.dataset.layer==='borders')$('.border-lines').style.opacity=b.classList.contains('selected')?'.63':'.12';if(b.dataset.layer==='conflicts')$$('.marker').forEach(m=>{const e=EVENTS.find(x=>x.id===m.dataset.event);m.style.opacity=b.classList.contains('selected')&&(e.category.includes('conflict')||e.category.includes('crisis'))?'1':b.classList.contains('selected')?'.3':'1'})});$('#layers-button').onclick=()=>notify('Select a layer to show or hide it.');$('#sound-toggle').onclick=()=>notify('Ambient audio is not included in this field edition.');document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#map-search').focus()}if(e.key==='Escape'){closeModal();$('#archivist-panel').classList.remove('open')}})}
function zoom(delta){if(worldMap)worldMap.zoomTo(Math.max(.15,Math.min(13,worldMap.getZoom()+delta)),{duration:430,essential:true})}
function updateZoom(){if(worldMap)worldMap.flyTo({center:[12,22],zoom:1.55,pitch:13,bearing:0,duration:1100,essential:true})}
function resetMapView(){if(worldMap){if(selectedMapEvent&&worldMap.getSource('campaign-events'))worldMap.setFeatureState({source:'campaign-events',id:selectedMapEvent},{selected:false});mapDidInitialFit=false;worldMap.resize();fitWholeWorld(1350);selectedMapEvent=null}else initializeMap()}
function applyPeriodFilter(){if(!worldMap?.getLayer('event-dots'))return;const era=Number($('#period-range').value);const filter=era===5?['all']:era===4?['>=',['get','year'],1900]:era===3?['all',['>=',['get','year'],1750],['<',['get','year'],1900]]:era===2?['all',['>=',['get','year'],1500],['<',['get','year'],1750]]:era===1?['all',['>=',['get','year'],500],['<',['get','year'],1500]]:['<',['get','year'],500];const unclustered=['!', ['has','point_count']],visibleFilter=['all',unclustered,filter];worldMap.setFilter('event-dots',visibleFilter);worldMap.setFilter('event-halo',visibleFilter);worldMap.setFilter('event-labels',visibleFilter);const names=['ANCIENT','MEDIEVAL','EARLY MODERN','INDUSTRIAL','20TH CENTURY','ALL ERAS'];$('#world-era').textContent=names[era];EVENTS.forEach(event=>{const card=$(`.event-card[data-event="${event.id}"]`);if(card)card.classList.toggle('era-muted',era!==5&&!matchesEra(event.year,era))})}
function matchesEra(year,era){return era===4?year>=1900:era===3?year>=1750&&year<1900:era===2?year>=1500&&year<1750:era===1?year>=500&&year<1500:era===0?year<500:true}
function toggleMapLayer(layer,button){button.classList.toggle('selected');const visible=button.classList.contains('selected');if(layer==='campaigns'&&worldMap?.getLayer('event-dots'))['event-clusters','event-cluster-count','event-dots','event-halo','event-labels'].filter(id=>worldMap.getLayer(id)).forEach(id=>worldMap.setLayoutProperty(id,'visibility',visible?'visible':'none'));if(layer==='routes'&&worldMap?.getLayer('trade-routes-line'))worldMap.setLayoutProperty('trade-routes-line','visibility',visible?'visible':'none');if(layer==='conflicts'&&worldMap?.getLayer('event-dots')){const conflict=['Military conflict','Nuclear crisis','Economic crisis'].includes(EVENTS.find(e=>e.id===selectedMapEvent)?.category);worldMap.setFilter('event-dots',visible?['any',['==',['get','category'],'Military conflict'],['==',['get','category'],'Nuclear crisis'],['==',['get','category'],'Economic crisis']]:['all']);worldMap.setFilter('event-halo',worldMap.getFilter('event-dots'));worldMap.setFilter('event-labels',worldMap.getFilter('event-dots'));}if(layer==='borders'&&worldMap){const ids=worldMap.getStyle().layers.filter(item=>/boundary|border/i.test(item.id)).map(item=>item.id);ids.forEach(id=>worldMap.setLayoutProperty(id,'visibility',visible?'visible':'none'));if(!ids.length)notify('Country borders are part of the current terrain style.')}}
function wireMapControls(){const zoomIn=$('#zoom-in'),zoomOut=$('#zoom-out'),reset=$('#reset-map'),search=$('#map-search'),period=$('#period-range'),panelToggle=$('#panel-toggle');if(zoomIn)zoomIn.onclick=()=>zoom(.75);if(zoomOut)zoomOut.onclick=()=>zoom(-.75);if(reset)reset.onclick=resetMapView;if(search)search.oninput=searchMap;if(period)period.oninput=applyPeriodFilter;if(panelToggle)panelToggle.onclick=()=>{const collapsed=$('#side-panel').classList.toggle('is-collapsed');panelToggle.textContent=collapsed?'EXPAND +':'COLLAPSE −';panelToggle.setAttribute('aria-expanded',String(!collapsed))};$$('.layer-chip').forEach(button=>button.onclick=()=>toggleMapLayer(button.dataset.layer,button));$('#layers-button').onclick=()=>notify('Use the layer chips to toggle campaign markers, boundaries, and routes.')}
function searchMap(){const input=$('#map-search'),q=input.value.trim(),results=$('#search-results');clearTimeout(geocodeTimer);if(!q){results.classList.add('hidden');return}const matches=EVENTS.filter(event=>`${event.title} ${event.place} ${event.category}`.toLowerCase().includes(q.toLowerCase()));results.innerHTML=matches.slice(0,4).map(event=>`<button class="search-result" data-event="${event.id}"><span>✦</span><b>${esc(event.title)}</b><small>${esc(event.place)}</small></button>`).join('')||'';results.classList.remove('hidden');$$('.search-result[data-event]',results).forEach(button=>button.onclick=()=>{const id=button.dataset.event;results.classList.add('hidden');input.value='';selectMarker(id)});geocodeTimer=setTimeout(()=>searchPlaces(q,results),360)}
async function searchPlaces(query,results){try{const response=await fetch(`https://photon.komoot.io/api/?q=${encodeURIComponent(query)}&limit=5&lang=en`);if(!response.ok)return;const data=await response.json();const features=(data.features||[]).slice(0,5);const html=features.map(feature=>{const p=feature.properties||{},coords=feature.geometry?.coordinates;if(!coords)return'';const title=p.name||p.city||p.street||p.county||'Unnamed location',context=[p.city&&p.city!==title?p.city:'',p.state,p.country].filter(Boolean).join(', ');return `<button class="search-result place-result" data-lng="${coords[0]}" data-lat="${coords[1]}" data-title="${esc(title)}" data-country="${esc(p.country||'')}"><span>⌖</span><b>${esc(title)}</b><small>${esc(context)}</small></button>`}).join('');if(html&&$('#map-search').value.trim().toLowerCase()===query.toLowerCase())results.insertAdjacentHTML('beforeend',html);$$('.place-result',results).forEach(button=>button.onclick=()=>{const {lng,lat,title,country}=button.dataset;results.classList.add('hidden');$('#map-search').value='';focusPlace(Number(lng),Number(lat),title,country)})}catch{if(!results.children.length)results.innerHTML='<div class="search-result">Place search is offline. Event search remains available.</div>'}}
function focusPlace(lng,lat,name,country){worldMap?.flyTo({center:[lng,lat],zoom:Math.max(worldMap.getZoom(),5.2),pitch:28,duration:1700,essential:true,curve:1.35});setSelectedPoint(lng,lat);$('#map-tooltip').textContent=[name,country].filter(Boolean).join(', ');$('#map-tooltip').classList.remove('hidden');const related=EVENTS.filter(event=>`${event.place} ${event.title}`.toLowerCase().includes((country||name).toLowerCase()));showLocationBriefing(name,country,related,lng,lat)}

window.COPRuntime={context(){const event=EVENTS.find(x=>x.id===(game?.eventId||selectedMapEvent))||EVENTS.find(x=>x.id==='emergency')||EVENTS[0];if(!event)return null;const scenario=scenarioFor(event);return{eventId:event.id,date:game?.date||scenario.date,role:game?.role||scenario.roles[0],state:game?.state||{...INITIAL_STATE},turn:game?.turn||game?.node||0,decisions:(game?.entries||[]).filter(x=>x.kind==='hypothetical').slice(-6).map(x=>x.text),counterpart:(event.people||[])[0]||(event.countries||[]).find(x=>x!==game?.role)||event.country||'Historical counterpart',eventTitle:event.title};},currentGame(){return game?JSON.parse(JSON.stringify(game)):null;},setActiveSaveId(id,revision){if(game){game._serverSaveId=id;game._serverRevision=revision;}},restoreSavedGame(value,saveId,revision){const campaign=value?.campaignId==='emergency'&&validGame(value),scenario=value?.eventId&&COPSimulation.validateSave(value,Math.max(0,value.node||0))&&EVENTS.some(event=>event.id===value.eventId);if(!campaign&&!scenario)return false;game={...value,_serverSaveId:saveId,_serverRevision:revision};if(scenario)renderGenericGame('Saved game restored from your account.');else renderGame();return true;},apply(action,generatedEvent){submitGenericAction(action,generatedEvent);},legacyAdvisor(question){answerArchivist(question);},addChat(who,text){addChat(who,text);}};
